// HasConfirmerWith applies the HasEdge predicate on the "confirmer" edge with a given conditions (other predicates).
func HasConfirmerWith(preds ...predicate.User) predicate.AgreementCompletion {
	return predicate.AgreementCompletion(func(s *sql.Selector) {
		step := newConfirmerStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.AgreementCompletion) predicate.AgreementCompletion {
	return predicate.AgreementCompletion(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.AgreementCompletion) predicate.AgreementCompletion {
	return predicate.AgreementCompletion(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.AgreementCompletion) predicate.AgreementCompletion {
	return predicate.AgreementCompletion(sql.NotPredicates(p))
}
